-- 外研社八上 wy8A 听力灌库(junior_listening_exercises)· publisher=junior_fltrp · volume=wy8A · grade=8 · 6单元×6=36
-- 3对话+2独白+1通知/单元 · 每篇2题4选1 · UK英音单音色(speaker=fable) · audio_url先NULL(跑pregenerate --volume=wy8A后回填)
-- 语法点:U1/U2现在完成时 U3不定式和动名词作宾语 U4不定式作宾补 U5目的状语不定式 U6过去进行时
-- ★DELETE 带 publisher='junior_fltrp' AND volume='wy8A' 双限★
BEGIN;
DELETE FROM public.junior_listening_exercises WHERE publisher='junior_fltrp' AND volume='wy8A';
INSERT INTO public.junior_listening_exercises
  (id, grade, publisher, volume, unit, title, topic, transcript, translation_cn, audio_url, speaker, kind, duration_sec, difficulty, questions, key_vocab) VALUES
  ('895495a3-e534-2969-ec23-eb895aed18d2', 8, 'junior_fltrp', 'wy8A', 'U1', 'Have you ever tried it?', '谈经历(现在完成时)', 'A: Have you ever tried rock climbing, Ben?
B: Yes, I have! I tried it last summer at a camp.
A: Wow, was it scary?
B: A little at first. But I have never felt so brave before.
A: That sounds amazing. I have always wanted to try it.
B: You should! It has really changed how I see myself.', 'A:Ben,你试过攀岩吗?B:试过!去年夏天在营地试的。A:哇,吓人吗?B:一开始有点。但我从没觉得这么勇敢过。A:听着真棒,我一直想试试。B:你该试!它真的改变了我看自己的方式。', NULL, 'fable', 'dialogue', 29, 1, '[{"type": "choice", "q": "When did Ben try rock climbing?", "options": ["This morning.", "Last week.", "Last summer.", "Never."], "answer": "C", "explanation": "''I tried it last summer at a camp.''"}, {"type": "choice", "q": "How has rock climbing changed Ben?", "options": ["It has made him tired.", "It has made him afraid.", "It has changed nothing.", "It has made him feel braver about himself."], "answer": "D", "explanation": "''It has really changed how I see myself.''"}]'::jsonb, '[{"word": "climbing", "cn": "攀爬,攀岩"}, {"word": "brave", "cn": "勇敢的"}, {"word": "scary", "cn": "吓人的"}]'::jsonb),
  ('4601d95d-c694-02e3-2a22-47297b22b9cb', 8, 'junior_fltrp', 'wy8A', 'U1', 'I''ve grown taller', '成长变化(现在完成时)', 'A: Lily, you look different! Have you changed your hair?
B: No, but I''ve grown taller this year. Look, I can reach the top shelf now!
A: That''s great! You''ve also become more confident.
B: Thanks. I''ve joined the drama club, and it has helped a lot.
A: I can tell. You speak more clearly now.
B: Growing up feels good, doesn''t it?', 'A:Lily你看着不一样了!换发型了?B:没,但我今年长高了。看,现在够得到最高层架子了!A:太好了!你也更自信了。B:谢谢,我加入了戏剧社,帮了很多。A:看得出,你现在说话更清楚了。B:长大感觉真好,对吧?', NULL, 'fable', 'dialogue', 34, 1, '[{"type": "choice", "q": "What club has Lily joined?", "options": ["The drama club.", "The music club.", "The art club.", "The sports club."], "answer": "A", "explanation": "''I''ve joined the drama club.''"}, {"type": "choice", "q": "How has Lily changed this year?", "options": ["She has changed her hair.", "She has grown taller and more confident.", "She has become quieter.", "She has left school."], "answer": "B", "explanation": "长高、更自信、说话更清楚。"}]'::jsonb, '[{"word": "confident", "cn": "自信的"}, {"word": "shelf", "cn": "架子"}, {"word": "drama", "cn": "戏剧"}]'::jsonb),
  ('399cfd54-942a-ffc5-17e5-0b7e8f2ca046', 8, 'junior_fltrp', 'wy8A', 'U1', 'Have you finished yet?', '完成情况(现在完成时·yet/already)', 'A: Have you finished your art project yet, Sam?
B: Almost. I''ve painted the sky, but I haven''t drawn the trees yet.
A: You''ve done a lot already! It looks wonderful.
B: Thanks. I''ve worked on it for three days.
A: Well, take your time. Have you shown it to the teacher?
B: Not yet. I want to finish it first.', 'A:Sam,美术作业做完了吗?B:快了。天空画好了,但树还没画。A:你已经做了很多了!看着真棒。B:谢谢,我做了三天了。A:慢慢来。给老师看过了吗?B:还没,我想先做完。', NULL, 'fable', 'dialogue', 32, 2, '[{"type": "choice", "q": "What has Sam not done yet?", "options": ["Drawn the trees.", "Painted the sky.", "Worked on the project.", "Shown the teacher."], "answer": "A", "explanation": "''I haven''t drawn the trees yet.''(树还没画,也还没给老师看)"}, {"type": "choice", "q": "How does A feel about Sam''s project?", "options": ["It is boring.", "It is unfinished and bad.", "It is too small.", "It looks wonderful and Sam has done a lot."], "answer": "D", "explanation": "''You''ve done a lot already! It looks wonderful.''"}]'::jsonb, '[{"word": "project", "cn": "作品,项目"}]'::jsonb),
  ('a91f99bf-fd2f-c54d-78cf-6958fdadc137', 8, 'junior_fltrp', 'wy8A', 'U1', 'How I have changed', '独白·我的成长(现在完成时)', 'Three years ago, I was a shy and quiet boy. I have changed a lot since then. In primary school, I never spoke in class. But now I have joined the school radio club, and I talk to many students every week. I have also learnt to play the guitar. Music has given me confidence. My teachers now call me a brave young person. I am proud of who I have become, and this is just the start.', '三年前,我是个害羞安静的男孩。从那时起我变了很多。小学时我从不在课上发言。但现在我加入了学校广播社,每周和许多同学说话。我还学会了弹吉他。音乐给了我自信。老师说我长成了一个勇敢的年轻人。我为自己成为的样子自豪,而且我知道这才刚开始。', NULL, 'fable', 'passage', 43, 1, '[{"type": "choice", "q": "What has the writer learnt to play?", "options": ["The piano.", "The drums.", "The guitar.", "The violin."], "answer": "C", "explanation": "''I have also learnt to play the guitar.''"}, {"type": "choice", "q": "What is the passage mainly about?", "options": ["How to play the guitar.", "How the writer has changed and grown more confident.", "Why primary school is hard.", "How to join a club."], "answer": "B", "explanation": "全文讲作者从害羞到自信的成长。"}]'::jsonb, '[{"word": "shy", "cn": "害羞的"}, {"word": "radio", "cn": "广播"}, {"word": "confidence", "cn": "自信"}]'::jsonb),
  ('cf5301d8-a6f3-3e19-38f7-de2bc4696bae', 8, 'junior_fltrp', 'wy8A', 'U1', 'A gift that changed me', '独白·改变我的礼物(现在完成时)', 'Two years ago, my uncle gave me an old camera. Since that day, it has changed my life. At first, I just took photos of my family. But I have slowly learnt to see the world in a new way. I have taken hundreds of photos of streets, trees and quiet mornings. Photography has taught me to look closely and to be patient. I have won a small prize at a school show, but the real gift is how much I have grown. I have found something I truly love.', '两年前,叔叔给了我一台旧相机。从那天起,它改变了我的生活。起初我只拍家人。但我慢慢学会了用新的方式看世界。我拍了几百张街道、树木和安静清晨的照片。摄影教会我细看、耐心。我在校展上得过一个小奖,但真正的礼物是我成长了多少。我找到了真正热爱的东西。', NULL, 'fable', 'passage', 49, 2, '[{"type": "choice", "q": "What did the writer''s uncle give?", "options": ["A guitar.", "A book.", "An old camera.", "A prize."], "answer": "C", "explanation": "''my uncle gave me an old camera.''"}, {"type": "choice", "q": "What has the camera done for the writer?", "options": ["It has made the writer rich.", "It has taken up too much time.", "It has changed nothing.", "It has helped the writer grow and find a real love."], "answer": "D", "explanation": "结尾:找到真爱、成长了。"}]'::jsonb, '[{"word": "camera", "cn": "相机"}, {"word": "photography", "cn": "摄影"}, {"word": "patient", "cn": "有耐心的"}]'::jsonb),
  ('54021e4f-2e03-e134-6afa-8c62947ab15d', 8, 'junior_fltrp', 'wy8A', 'U1', 'My Story Week', '通知·成长故事周(现在完成时)', 'Hello, students. Here is some news about our My Story Week. This term, many of you have grown and changed a lot. Next week, we will share our stories. On Monday, you can write about a skill you have learnt. On Wednesday, we will show photos of how we have changed. On Friday, come and tell your story on the stage. Everyone has a story to share!', '同学们好,关于成长故事周的通知。这学期,你们许多人以美好的方式成长和改变。下周我们分享成长故事。周一,写一项你学会的技能。周三,展示我们如何改变的照片。周五,来台上讲你的故事。每个人都有值得分享的故事。我们迫不及待想听你的!', NULL, 'fable', 'notice', 37, 1, '[{"type": "choice", "q": "What will students do on Friday?", "options": ["Write about a skill.", "Tell their story on the stage.", "Show photos.", "Clean the hall."], "answer": "B", "explanation": "''On Friday, come and tell your story on the stage.''"}, {"type": "choice", "q": "What is My Story Week about?", "options": ["Sharing how students have grown and changed.", "A sports match.", "A photo sale.", "A maths test."], "answer": "A", "explanation": "通知主体=分享成长变化。"}]'::jsonb, '[{"word": "term", "cn": "学期"}, {"word": "skill", "cn": "技能"}]'::jsonb),
  ('43f6eb22-6021-d2df-c4dc-bb06867cb7d4', 8, 'junior_fltrp', 'wy8A', 'U2', 'We''ve made up', '和好(现在完成时)', 'A: You look happy, Kate. What''s up?
B: Lucy and I have made up! We had a quarrel last week.
A: Oh, I''m glad. What happened?
B: I''ve said sorry, and she has forgiven me. We''re good friends again.
A: That''s wonderful. Friends have ups and downs.
B: True. I''ve learnt that a real friend is worth keeping.', 'A:Kate你看着开心,怎么了?B:Lucy和我和好了!上周我们吵了架。A:哦太好了,怎么回事?B:我道了歉,她原谅了我,我们又是好朋友了。A:真好,朋友总有起起落落。B:是的,我懂了真正的朋友值得珍惜。', NULL, 'fable', 'dialogue', 32, 1, '[{"type": "choice", "q": "What has Kate done to make up with Lucy?", "options": ["Bought a gift.", "Written a letter.", "Said sorry.", "Called her mum."], "answer": "C", "explanation": "''I''ve said sorry, and she has forgiven me.''"}, {"type": "choice", "q": "What has Kate learnt?", "options": ["Quarrels are fun.", "A real friend is worth keeping.", "Friends are not important.", "She should stay quiet."], "answer": "B", "explanation": "''a real friend is worth keeping.''"}]'::jsonb, '[{"word": "quarrel", "cn": "争吵"}, {"word": "forgiven", "cn": "原谅(forgive的过去分词)"}]'::jsonb),
  ('3f5ed540-bb22-5ee6-1fe2-2f1201b89b60', 8, 'junior_fltrp', 'wy8A', 'U2', 'Old neighbours', '老邻居(完成时2·for/since延续+gone to)', 'A: Have you known the Green family for a long time?
B: Yes, we''ve been neighbours for ten years. They''ve lived here since I was small.
A: That''s a long time! Are they still next door?
B: Mr and Mrs Green are. But their son Tom has gone to university in another city.
A: Oh, so the house feels quieter now.
B: A little. But we''ve known them for so long that they feel like family.', 'A:你认识Green一家很久了吗?B:是的,我们做邻居十年了,他们从我小时候就住这儿。A:很久了!他们还住隔壁吗?B:Green夫妇还在,但他们儿子Tom去外地上大学了。A:哦,房子现在安静些了。B:有点,但我们认识这么久,他们就像家人。', NULL, 'fable', 'dialogue', 40, 2, '[{"type": "choice", "q": "How long have they been neighbours?", "options": ["Two years.", "Five years.", "One year.", "Ten years."], "answer": "D", "explanation": "''we''ve been neighbours for ten years.''"}, {"type": "choice", "q": "Why does the house feel quieter now?", "options": ["Their son has gone to university in another city.", "The Greens have moved away.", "Nobody lives there.", "They have a new baby."], "answer": "A", "explanation": "''their son Tom has gone to university in another city.''(gone to=去了未回)"}]'::jsonb, '[{"word": "neighbour", "cn": "邻居"}, {"word": "university", "cn": "大学"}]'::jsonb),
  ('9af458d0-3854-73ae-2f75-aeef49552d8d', 8, 'junior_fltrp', 'wy8A', 'U2', 'Have you thanked her?', '表达感谢(现在完成时)', 'A: Ms Wu has helped me so much this term.
B: Have you thanked her yet?
A: Not really. I''ve been shy about it.
B: You should. A simple ''thank you'' means a lot.
A: You''re right. I''ve decided to write her a card.
B: Great idea. She has always cared about her students.', 'A:吴老师这学期帮了我好多。B:你谢过她了吗?A:还没,我不好意思。B:该谢,一句简单的谢谢意义很大。A:你说得对,我决定给她写张卡片。B:好主意,她一直很关心学生。', NULL, 'fable', 'dialogue', 28, 1, '[{"type": "choice", "q": "What has A decided to do?", "options": ["Buy a gift.", "Say nothing.", "Write a card.", "Call her."], "answer": "C", "explanation": "''I''ve decided to write her a card.''"}, {"type": "choice", "q": "What does the dialogue mainly tell us?", "options": ["Teachers are strict.", "We should thank people who help us.", "Cards are expensive.", "Being shy is good."], "answer": "B", "explanation": "主题=感谢帮助我们的人。"}]'::jsonb, '[{"word": "card", "cn": "卡片"}]'::jsonb),
  ('c936de9a-8f87-63db-bf36-0e24378789a3', 8, 'junior_fltrp', 'wy8A', 'U2', 'My best friend', '独白·友谊(完成时2·for/since+been to/gone to)', 'Anna and I have been friends for eight years. We have known each other since we were six. Over the years, we have shared many happy and hard times, and we have always made up after our quarrels. Last month, Anna moved to a new town, so she has gone to a different school now. I have already been to her new home once, and it is lovely. We still talk every evening. A true friend stays close in your heart, even far away.', 'Anna和我做朋友八年了。我们从六岁起就认识。这些年,我们分享了许多快乐和艰难,吵架后也总能和好。上个月Anna搬到新城,所以她现在去了另一所学校。我已经去过她的新家一次,那里很可爱。我们仍每晚聊天。真正的朋友即使远隔,也在你心里很近。', NULL, 'fable', 'passage', 46, 1, '[{"type": "choice", "q": "How long have Anna and the writer been friends?", "options": ["Eight years.", "Six years.", "Ten years.", "Two years."], "answer": "A", "explanation": "''we have been friends for eight years.''"}, {"type": "choice", "q": "What is the passage mainly about?", "options": ["How to win a quarrel.", "Why moving is hard.", "How to make new friends.", "A true friendship stays close even when friends are far apart."], "answer": "D", "explanation": "结尾:真朋友远隔也在心里近。"}]'::jsonb, '[{"word": "quarrel", "cn": "争吵"}, {"word": "true", "cn": "真正的"}]'::jsonb),
  ('a8674f8e-8b31-bb3b-31d2-47f0bf5f7883', 8, 'junior_fltrp', 'wy8A', 'U2', 'Getting along at home', '独白·家庭相处(现在完成时)', 'Living with a younger brother is not always easy. In the past, my brother and I fought over small things. But this year, something has changed. I have learnt to be more patient, and he has learnt to share. When he breaks my things, I try not to shout. When I am tired, he brings me water. We have started to help each other more. Our home has become warmer because of these small changes. Getting along takes time, but it is worth it.', '和弟弟一起生活并不总是容易。过去我和弟弟为小事争吵。但今年,有些东西变了。我学会了更有耐心,他学会了分享。他弄坏我的东西时,我尽量不吼。我累的时候,他给我端水。我们开始更多地互相帮助。因为这些小变化,我们的家变得更温暖了。相处需要时间,但值得。', NULL, 'fable', 'passage', 46, 2, '[{"type": "choice", "q": "What has the writer learnt this year?", "options": ["To shout louder.", "To be more patient.", "To share toys.", "To stay away."], "answer": "B", "explanation": "''I have learnt to be more patient.''"}, {"type": "choice", "q": "What is the main idea?", "options": ["Younger brothers are annoying.", "Fighting is normal.", "Small changes have helped them get along better at home.", "Home is boring."], "answer": "C", "explanation": "全文讲小变化让家人相处更好。"}]'::jsonb, '[{"word": "patient", "cn": "有耐心的"}, {"word": "fought", "cn": "争吵(fight的过去式)"}]'::jsonb),
  ('855a6d8d-7d55-b594-a9bc-8ff8343fcb69', 8, 'junior_fltrp', 'wy8A', 'U2', 'Kindness Week', '通知·友善周(现在完成时)', 'Hello, students. Here is some news about our Kindness Week. This term, many of you have shown great kindness to others. Next week, let''s do even more. On Monday, thank a friend who has helped you. On Wednesday, make a new classmate feel welcome. On Friday, write a kind note to someone. Small acts of kindness make our school a warmer place. Let''s get along and care for each other!', '同学们好,关于友善周的通知。这学期,你们许多人对他人展现了极大的善意。下周,让我们做得更多。周一,感谢一位帮过你的朋友。周三,让一位新同学感到受欢迎。周五,给某人写一张友善的便条。小小的善举让校园更温暖。让我们和睦相处、互相关心!', NULL, 'fable', 'notice', 39, 1, '[{"type": "choice", "q": "What should students do on Wednesday?", "options": ["Thank a friend.", "Write a note.", "Clean the hall.", "Make a new classmate feel welcome."], "answer": "D", "explanation": "''On Wednesday, make a new classmate feel welcome.''"}, {"type": "choice", "q": "What is Kindness Week about?", "options": ["Being kind and getting along with others.", "A sports match.", "A book sale.", "A maths test."], "answer": "A", "explanation": "通知主体=友善与相处。"}]'::jsonb, '[{"word": "kindness", "cn": "善意,友善"}, {"word": "note", "cn": "便条"}]'::jsonb),
  ('da771765-e0a4-562d-f314-f4d37c46f618', 8, 'junior_fltrp', 'wy8A', 'U3', 'I want to be a doctor', '谈梦想(不定式作宾语)', 'A: What do you want to be in the future, Ben?
B: I want to be a doctor. I hope to help sick people.
A: That''s a great dream! It needs a lot of work, though.
B: I know. I''ve decided to study science harder.
A: Good for you. I plan to become a teacher myself.
B: Then let''s both keep working towards our dreams!', 'A:Ben,你将来想做什么?B:我想当医生,希望帮助生病的人。A:好梦想!不过要下很多功夫。B:我知道,我决定更努力学科学。A:真棒,我自己打算当老师。B:那我们都朝梦想努力吧!', NULL, 'fable', 'dialogue', 34, 1, '[{"type": "choice", "q": "What does Ben want to be?", "options": ["A teacher.", "A scientist.", "A doctor.", "A player."], "answer": "C", "explanation": "''I want to be a doctor.''"}, {"type": "choice", "q": "What do the two friends decide to do?", "options": ["Keep working towards their dreams.", "Give up their dreams.", "Change schools.", "Stop studying."], "answer": "A", "explanation": "结尾:一起朝梦想努力。"}]'::jsonb, '[{"word": "future", "cn": "未来"}, {"word": "sick", "cn": "生病的"}]'::jsonb),
  ('5841aeac-f284-4526-1732-49cdc67be8a4', 8, 'junior_fltrp', 'wy8A', 'U3', 'Keep practising', '坚持练习(动名词作宾语)', 'A: You play the piano so well, Lily! How did you do it?
B: I just kept practising every day. I really enjoy playing.
A: But isn''t it boring to practise the same thing?
B: Sometimes. But I love making music, so I don''t mind practising.
A: I want to learn too. Where should I start?
B: Start with simple songs, and don''t give up trying!', 'A:Lily你钢琴弹得真好!怎么做到的?B:我就是每天坚持练。我真的喜欢弹。A:可老练同一样东西不无聊吗?B:有时候。但我爱创作音乐,所以不介意练习。A:我也想学,该从哪开始?B:从简单的歌开始,别放弃尝试!', NULL, 'fable', 'dialogue', 34, 2, '[{"type": "choice", "q": "How did Lily play the piano so well?", "options": ["She took a class.", "She watched videos.", "She has a good teacher.", "She kept practising every day."], "answer": "D", "explanation": "''I just kept practising every day.''"}, {"type": "choice", "q": "What is Lily''s advice to A?", "options": ["Practise once a week.", "Start simple and don''t give up trying.", "Only play hard songs.", "Stop when it is boring."], "answer": "B", "explanation": "''Start with simple songs, and don''t give up trying.''"}]'::jsonb, '[{"word": "piano", "cn": "钢琴"}]'::jsonb),
  ('ff037712-bb13-4778-129d-95b259842f88', 8, 'junior_fltrp', 'wy8A', 'U3', 'Planning the show', '筹划演出(不定式/动名词)', 'A: We''ve decided to put on a class show. Will you join?
B: Sure! I enjoy singing. What do you need me to do?
A: We hope to have songs, dances and a short play.
B: Sounds fun! I''d love to help with the singing.
A: Great. Let''s start planning right away.
B: I can''t wait to see everyone''s talent!', 'A:我们决定办个班级演出,你参加吗?B:当然!我喜欢唱歌。你要我做什么?A:我们希望有歌曲、舞蹈和一个短剧。B:听着有趣!我很乐意帮唱歌的部分。A:太好了,我们马上开始筹划。B:等不及看大家的才艺了!', NULL, 'fable', 'dialogue', 32, 1, '[{"type": "choice", "q": "What part does B want to help with?", "options": ["The singing.", "The dancing.", "The play.", "The lights."], "answer": "A", "explanation": "''I''d love to help with the singing.''"}, {"type": "choice", "q": "What are they planning?", "options": ["A maths test.", "A sports day.", "A class show with songs, dances and a play.", "A trip."], "answer": "C", "explanation": "筹划班级演出。"}]'::jsonb, '[{"word": "show", "cn": "演出"}]'::jsonb),
  ('dedf4a18-1ca9-6dea-f6a7-0194de4cbb9b', 8, 'junior_fltrp', 'wy8A', 'U3', 'Never stop trying', '独白·坚持追梦(不定式/动名词)', 'When I was ten, I decided to learn to swim. At first, I was afraid of the water and wanted to give up. But my coach told me to keep trying. So I practised every weekend. I learnt to hold my breath, and slowly I started to enjoy swimming. Last month, I finished my first race. I did not win, but I felt proud. I have learnt that reaching a dream means never giving up. Now I hope to try even harder next year.', '十岁时,我决定学游泳。起初我怕水,想放弃。但教练叫我坚持。于是我每个周末练。我学会了憋气,慢慢开始享受游泳。上个月我完成了第一场比赛。我没赢,但很自豪。我懂得,实现梦想意味着永不放弃。现在我希望明年更努力。', NULL, 'fable', 'passage', 46, 1, '[{"type": "choice", "q": "What did the coach tell the writer to do?", "options": ["To give up.", "To keep trying.", "To swim faster.", "To rest more."], "answer": "B", "explanation": "''my coach told me to keep trying.''"}, {"type": "choice", "q": "What has the writer learnt?", "options": ["Swimming is easy.", "Winning is everything.", "Coaches are strict.", "Reaching a dream means never giving up."], "answer": "D", "explanation": "''reaching a dream means never giving up.''"}]'::jsonb, '[{"word": "coach", "cn": "教练"}, {"word": "breath", "cn": "呼吸"}]'::jsonb),
  ('67c6bab7-8240-2b02-3155-7bee858b9f1f', 8, 'junior_fltrp', 'wy8A', 'U3', 'The power of small steps', '独白·小步坚持(动名词/不定式)', 'Many people want to do great things, but they forget to start small. Last year, I hoped to read more books. Reading a whole book felt too hard, so I decided to read just ten pages a day. I kept doing this every night. Soon, I finished one book, then another. By the end of the year, I had read twenty books. Doing a little every day really works. If you keep taking small steps, you will reach your goal before you know it.', '很多人想做大事,却忘了从小处开始。去年我希望多读书。读完一整本觉得太难,于是我决定每天只读十页。我每晚坚持这样做。很快,我读完一本,又一本。到年底,我读了二十本。每天做一点真的管用。只要坚持迈小步,你会在不知不觉中实现目标。', NULL, 'fable', 'passage', 46, 2, '[{"type": "choice", "q": "How many pages did the writer decide to read a day?", "options": ["Ten.", "Five.", "Twenty.", "Fifty."], "answer": "A", "explanation": "''I decided to read just ten pages a day.''"}, {"type": "choice", "q": "What is the main idea?", "options": ["Reading is boring.", "Doing a little every day helps you reach a big goal.", "Great things are easy.", "Books are expensive."], "answer": "B", "explanation": "全文讲小步坚持实现大目标。"}]'::jsonb, '[{"word": "pages", "cn": "页"}, {"word": "goal", "cn": "目标"}]'::jsonb),
  ('e6c6e87e-99fa-1a17-a0f3-7fd63470a933', 8, 'junior_fltrp', 'wy8A', 'U3', 'Dream Big Day', '通知·梦想日(不定式/动名词)', 'Hello, students. Here is some news about our Dream Big Day. Next Friday, we want to help you plan your dreams. In the morning, you can write down one goal you hope to reach. At noon, older students will share how they keep working towards their dreams. In the afternoon, we will start a ''small steps'' plan together. Don''t be afraid to dream. Come and start making your dream happen!', '同学们好,关于梦想日的通知。下周五,我们想帮你规划梦想。上午,写下一个你希望实现的目标。中午,高年级同学分享他们如何朝梦想努力。下午,我们一起启动「小步」计划。别怕做梦。来,开始让你的梦想成真!', NULL, 'fable', 'notice', 39, 1, '[{"type": "choice", "q": "What can students write down in the morning?", "options": ["A song.", "A story.", "One goal they hope to reach.", "A photo."], "answer": "C", "explanation": "''write down one goal you hope to reach.''"}, {"type": "choice", "q": "What is Dream Big Day about?", "options": ["A sports match.", "A food festival.", "A maths test.", "Helping students plan and start their dreams."], "answer": "D", "explanation": "通知主体=帮学生规划、启动梦想。"}]'::jsonb, '[{"word": "goal", "cn": "目标"}]'::jsonb),
  ('4d4395bb-abc0-6776-3be6-df925a62aa23', 8, 'junior_fltrp', 'wy8A', 'U4', 'Too much screen time', '屏幕时间(不定式作宾补)', 'A: Mum wants me to spend less time on my phone.
B: Mine does too. She always tells me to put it away at dinner.
A: I know it''s better for us. But it''s so hard to stop!
B: My dad asked me to try a screen-free hour every evening.
A: Did it work?
B: Yes! It helped me sleep better. You should try it too.', 'A:妈妈想让我少玩手机。B:我妈也是,她总叫我吃饭时把手机收起来。A:我知道这对我们更好,但太难停下了!B:我爸让我每晚试一个无屏幕时间。A:有用吗?B:有!它帮我睡得更好,你也该试试。', NULL, 'fable', 'dialogue', 34, 1, '[{"type": "choice", "q": "What did B''s dad ask him to try?", "options": ["A new phone.", "A screen-free hour every evening.", "A longer game.", "A later dinner."], "answer": "B", "explanation": "''My dad asked me to try a screen-free hour every evening.''"}, {"type": "choice", "q": "What is the dialogue mainly about?", "options": ["Buying a new phone.", "Playing more games.", "Watching TV.", "Spending less time on phones."], "answer": "D", "explanation": "主题=少玩手机、控制屏幕时间。"}]'::jsonb, '[{"word": "screen", "cn": "屏幕"}]'::jsonb),
  ('486aa332-14ba-8cf8-bcf3-16924ac28196', 8, 'junior_fltrp', 'wy8A', 'U4', 'Help me with the app', '求助用软件(不定式作宾补)', 'A: Ben, can you help me use this new study app?
B: Sure. First, I need you to sign in with your school name.
A: OK, done. What next?
B: Now I want you to choose the maths lessons you like.
A: Got it. This is really useful!
B: It is. It helps us learn at our own speed.', 'A:Ben,你能帮我用这个新学习软件吗?B:当然。首先,我要你用学校名字登录。A:好,登好了,然后呢?B:现在我想让你选你喜欢的数学课。A:懂了,这真有用!B:是的,它帮我们按自己的节奏学。', NULL, 'fable', 'dialogue', 29, 2, '[{"type": "choice", "q": "What does B want A to choose?", "options": ["A new phone.", "A school name.", "The maths lessons A likes.", "A game."], "answer": "C", "explanation": "''I want you to choose the maths lessons you like.''"}, {"type": "choice", "q": "Why is the app useful?", "options": ["It helps students learn at their own speed.", "It plays music.", "It is a game.", "It is free."], "answer": "A", "explanation": "''It helps us learn at our own speed.''"}]'::jsonb, '[{"word": "app", "cn": "应用程序,软件"}, {"word": "sign in", "cn": "登录"}]'::jsonb),
  ('f7781579-346f-13f9-6bfa-55171d8c3dcb', 8, 'junior_fltrp', 'wy8A', 'U4', 'Stay safe online', '网络安全(不定式作宾补)', 'A: Our teacher told us to be careful online today.
B: Right. She asked us not to share our home address.
A: And she wants us to think before we click.
B: Yes. She also told us to tell an adult if something feels strange.
A: That''s good advice. The internet is useful but we need to be careful.
B: Exactly. Staying safe is up to us.', 'A:老师今天叫我们上网小心。B:对,她让我们别分享家庭住址。A:她还想让我们点击前想一想。B:是的,她也叫我们,如果觉得哪里不对就告诉大人。A:好建议。网络有用但我们必须小心。B:没错,保持安全靠我们自己。', NULL, 'fable', 'dialogue', 34, 1, '[{"type": "choice", "q": "What did the teacher ask them not to share?", "options": ["Their photos.", "Their names.", "Their books.", "Their home address."], "answer": "D", "explanation": "''She asked us not to share our home address.''"}, {"type": "choice", "q": "What is the teacher''s main advice?", "options": ["To stop using the internet.", "To stay safe and careful online.", "To share everything.", "To click quickly."], "answer": "B", "explanation": "主题=网络安全。"}]'::jsonb, '[{"word": "online", "cn": "在线,网上"}, {"word": "address", "cn": "地址"}]'::jsonb),
  ('8a29b834-021b-897d-30ed-2b22c8d06c49', 8, 'junior_fltrp', 'wy8A', 'U4', 'A smart phone habit', '独白·手机好习惯(不定式作宾补)', 'Last year, my phone controlled me. I played games late into the night, and my mum often asked me to stop. One day, my teacher told us to make a simple plan. So I decided to change. Now I put my phone in a box after nine o''clock. I let my family remind me if I forget. My parents also want me to read before bed instead. This small habit has helped me a lot. I sleep better, and I feel happier every morning.', '去年,手机控制着我。我玩游戏到深夜,妈妈常叫我停下。有一天,老师叫我们做个简单的计划。于是我决定改变。现在九点后我把手机放进盒子里。如果忘了,我让家人提醒我。父母还想让我睡前读书。这个小习惯帮了我很多。我睡得更好,每天早上更开心。', NULL, 'fable', 'passage', 46, 1, '[{"type": "choice", "q": "What does the writer do with the phone after nine o''clock?", "options": ["Plays games.", "Reads on it.", "Puts it in a box.", "Gives it to mum."], "answer": "C", "explanation": "''I put my phone in a box after nine o''clock.''"}, {"type": "choice", "q": "What is the passage mainly about?", "options": ["How a small habit helped the writer control phone use.", "How to play more games.", "Why phones are bad.", "How to buy a phone."], "answer": "A", "explanation": "全文讲小习惯帮控制手机。"}]'::jsonb, '[{"word": "control", "cn": "控制"}, {"word": "remind", "cn": "提醒"}]'::jsonb),
  ('49200bc6-1f30-62db-4f63-ac06e77e53fe', 8, 'junior_fltrp', 'wy8A', 'U4', 'Learning online', '独白·线上学习(不定式作宾补)', 'The internet has opened a new world for learning. Last winter, when I was ill at home, my teacher wanted me to keep up with the class. So she asked a classmate to send me the lessons online. Every evening, my friends helped me understand the hard parts through video calls. My parents also encouraged me to study a little each day. Thanks to them, I did not fall behind. The internet did not do the work for me, but it helped people work together.', '网络为学习打开了新世界。去年冬天我生病在家,老师想让我跟上班级进度。于是她叫一位同学把课程发到网上给我。每晚,朋友们通过视频通话帮我理解难的部分。父母也鼓励我每天学一点。多亏了他们,我没落下。网络没替我做作业,但它帮人们一起努力。', NULL, 'fable', 'passage', 46, 2, '[{"type": "choice", "q": "What did the teacher ask a classmate to do?", "options": ["To visit the writer.", "To call the parents.", "To send the lessons online.", "To bring food."], "answer": "C", "explanation": "''she asked a classmate to send me the lessons online.''"}, {"type": "choice", "q": "What does the passage tell us about the internet?", "options": ["It helped people work together for learning.", "It did all the work.", "It is only for games.", "It is not useful."], "answer": "A", "explanation": "结尾:网络帮人们一起努力。"}]'::jsonb, '[{"word": "video call", "cn": "视频通话"}, {"word": "encouraged", "cn": "鼓励(encourage的过去式)"}]'::jsonb),
  ('29878e46-f3b4-fc6c-2991-d5504e6441d2', 8, 'junior_fltrp', 'wy8A', 'U4', 'Digital Wisdom Day', '通知·数字素养日(不定式作宾补)', 'Hello, students. Here is some news about our Digital Wisdom Day. Next Friday, we want you to learn to use the internet in a safe way. In the morning, a teacher will show you how to check if a website is safe. At noon, we ask you to share one good learning app. In the afternoon, we want everyone to make a screen-time plan. Let''s learn to use the internet well!', '同学们好,关于数字素养日的通知。下周五,我们想让你学会聪明、安全地用网络。上午,老师教你怎么判断网站是否安全。中午,我们请你分享一个好的学习软件。下午,我们想让每个人做一个屏幕时间计划。网络是好工具。让我们学会用好它!', NULL, 'fable', 'notice', 40, 1, '[{"type": "choice", "q": "What does the school ask students to share at noon?", "options": ["A photo.", "One good learning app.", "A game.", "A song."], "answer": "B", "explanation": "''we ask you to share one good learning app.''"}, {"type": "choice", "q": "What is Digital Wisdom Day about?", "options": ["Buying phones.", "Playing games.", "A sports match.", "Learning to use the internet in a smart, safe way."], "answer": "D", "explanation": "通知主体=聪明安全用网络。"}]'::jsonb, '[{"word": "website", "cn": "网站"}]'::jsonb),
  ('3da1095f-0789-e919-e025-90032c339919', 8, 'junior_fltrp', 'wy8A', 'U5', 'Why wait in line?', '排队的意义(目的状语不定式)', 'A: Why do we always have to wait in line, Ben?
B: We wait in line to be fair to everyone.
A: I see. So no one pushes in front.
B: Right. Rules are there to keep things fair and safe.
A: That makes sense. I''ll be more patient next time.
B: Good! A little order helps everyone.', 'A:Ben,我们为什么总要排队?B:我们排队是为了对每个人公平。A:明白了,这样就没人插队。B:对,规则的存在是为了让事情公平安全。A:有道理,下次我会更耐心。B:很好!一点秩序帮到每个人。', NULL, 'fable', 'dialogue', 29, 1, '[{"type": "choice", "q": "Why do we wait in line, according to Ben?", "options": ["To be fair to everyone.", "To save time.", "To make friends.", "To rest."], "answer": "A", "explanation": "''We wait in line to be fair to everyone.''"}, {"type": "choice", "q": "What is the dialogue mainly about?", "options": ["How to push in front.", "Why lines are boring.", "How to run fast.", "Why rules like waiting in line matter."], "answer": "D", "explanation": "主题=规则(排队)的意义。"}]'::jsonb, '[{"word": "fair", "cn": "公平的"}, {"word": "order", "cn": "秩序"}]'::jsonb),
  ('80b1ead1-8f0c-9831-a255-0a16e1edf762', 8, 'junior_fltrp', 'wy8A', 'U5', 'Keep the park clean', '爱护公园(目的状语不定式)', 'A: Look, someone put their rubbish in the bin, not on the grass.
B: Good. We should all do that to keep the park clean.
A: I bring a small bag to collect my rubbish when I go out.
B: That''s a great habit! Small acts help to protect our city.
A: Right. If everyone helps, the park stays beautiful.
B: Let''s tell our friends to do the same.', 'A:看,有人把垃圾扔进垃圾桶,不是草地上。B:好,我们都该那样做,好让公园干净。A:我出门带个小袋子装自己的垃圾。B:好习惯!小小的举动帮助保护我们的城市。A:对,人人出力,公园就一直美。B:让我们叫朋友也这么做。', NULL, 'fable', 'dialogue', 35, 2, '[{"type": "choice", "q": "Why does A bring a small bag when going out?", "options": ["To carry books.", "To collect rubbish.", "To bring food.", "To hold water."], "answer": "B", "explanation": "''I bring a small bag to collect my rubbish.''"}, {"type": "choice", "q": "What is the main idea?", "options": ["Parks are boring.", "Rubbish is useful.", "Small acts help to keep the city clean.", "Bags are cheap."], "answer": "C", "explanation": "主题=小举动保护城市。"}]'::jsonb, '[{"word": "rubbish", "cn": "垃圾"}, {"word": "bin", "cn": "垃圾桶"}]'::jsonb),
  ('44765455-a297-8752-4fec-0e4b2452089b', 8, 'junior_fltrp', 'wy8A', 'U5', 'Getting up early', '早起的目的(目的状语不定式)', 'A: You look tired, Lily. Why do you get up so early?
B: I get up early to read English before school.
A: Every day? That takes real effort.
B: It does. I do it to reach my goal step by step.
A: That''s inspiring. Maybe I should start too.
B: Try it! We work hard now to have a better future.', 'A:Lily你看着累,为什么起这么早?B:我早起是为了上学前读英语。A:每天?那要真功夫。B:是的,我这么做是为了一步步实现目标。A:真励志,也许我也该开始。B:试试!我们现在努力是为了有更好的未来。', NULL, 'fable', 'dialogue', 31, 1, '[{"type": "choice", "q": "Why does Lily get up early?", "options": ["To play games.", "To eat breakfast.", "To walk the dog.", "To read English before school."], "answer": "D", "explanation": "''I get up early to read English before school.''"}, {"type": "choice", "q": "What does Lily believe?", "options": ["Sleep is a waste of time.", "Goals are not important.", "We work hard now to have a better future.", "Mornings are boring."], "answer": "C", "explanation": "''We work hard now to have a better future.''"}]'::jsonb, '[{"word": "effort", "cn": "努力"}, {"word": "goal", "cn": "目标"}]'::jsonb),
  ('fc01c57e-8bcf-aab7-a744-46a9364102c0', 8, 'junior_fltrp', 'wy8A', 'U5', 'Why we have rules', '独白·规则的意义(目的状语不定式)', 'Some students find rules boring, but rules are there to help us. We keep quiet in the library to let others read in peace. We walk, not run, in the halls to keep everyone safe. We put litter in the bin to keep our school clean. Even at home, we follow rules to live together happily. Rules do not stop our fun. They simply help many people share the same space. When we follow them, life becomes easier for all.', '有些学生觉得规则无聊,但规则的存在是为了帮我们。我们在图书馆安静,是为了让别人安心阅读。我们在走廊走不跑,是为了让大家安全。我们把垃圾扔进桶,是为了让学校干净。即使在家,我们遵守规则是为了一起快乐生活。规则不是为了阻止我们玩乐。它们是为了帮许多人共享同一空间。当我们遵守,生活对所有人都更容易。', NULL, 'fable', 'passage', 44, 1, '[{"type": "choice", "q": "Why do we keep quiet in the library?", "options": ["To sleep.", "To let others read in peace.", "To hide.", "To eat."], "answer": "B", "explanation": "''We keep quiet in the library to let others read in peace.''"}, {"type": "choice", "q": "What is the passage mainly about?", "options": ["Why we have rules and how they help everyone.", "Why rules are boring.", "How to break rules.", "Why libraries are quiet."], "answer": "A", "explanation": "全文讲规则的意义。"}]'::jsonb, '[{"word": "peace", "cn": "安宁,平静"}, {"word": "litter", "cn": "垃圾"}]'::jsonb),
  ('6b6b55f8-d76d-94f8-caa5-9da312d75d99', 8, 'junior_fltrp', 'wy8A', 'U5', 'A polite city', '独白·文明城市(目的状语不定式)', 'Last summer, I visited a city far away, and something impressed me. On the bus, young people stood up to give their seats to the old. At the crossing, cars stopped to let people walk. In shops, everyone waited in line to pay. No one shouted, and the streets were clean. These small, polite acts made the whole city feel warm. I came home and decided to do the same. To build a better place, we do not need big things. We just need to be kind every day.', '去年夏天,我去了一座很远的城市,有件事打动了我。公交上,年轻人站起来给老人让座。路口,汽车停下让人过。商店里,人人排队付钱。没人大喊,街道干净。这些小小的、文明的举动让整座城市感觉温暖。我回家后决定也这么做。要建一个更好的地方,我们不需要大事。我们只需要每天友善。', NULL, 'fable', 'passage', 49, 2, '[{"type": "choice", "q": "What did young people do on the bus?", "options": ["Shouted loudly.", "Slept.", "Ate food.", "Stood up to give seats to the old."], "answer": "D", "explanation": "''young people stood up to give their seats to the old.''"}, {"type": "choice", "q": "What is the writer''s main point?", "options": ["Cities are dirty.", "Rules do not work.", "To build a better place, we just need to be kind every day.", "Travel is expensive."], "answer": "C", "explanation": "结尾点题:每天友善建更好的地方。"}]'::jsonb, '[{"word": "impressed", "cn": "打动,留下印象"}, {"word": "crossing", "cn": "人行横道"}]'::jsonb),
  ('be7c0617-1f80-ff3a-0508-7aa6174158fc', 8, 'junior_fltrp', 'wy8A', 'U5', 'Be a Good Citizen Week', '通知·文明公民周(目的状语不定式)', 'Hello, students. Here is some news about our Be a Good Citizen Week. Next week, we will practise small acts to make our school and city better. On Monday, wait in line to show good order. On Wednesday, pick up litter to keep the ground clean. On Friday, help someone to be kind. We do these small things to build a warmer place for everyone. Come and join us!', '同学们好,关于文明公民周的通知。下周,我们将练习小举动,让学校和城市更好。周一,排队以展现良好秩序。周三,捡垃圾以保持地面干净。周五,帮助某人以示友善。我们做这些小事是为了给每个人建一个更温暖的地方。快来参加!', NULL, 'fable', 'notice', 38, 1, '[{"type": "choice", "q": "What should students do on Wednesday?", "options": ["Wait in line.", "Pick up litter.", "Help someone.", "Clean the hall."], "answer": "B", "explanation": "''On Wednesday, pick up litter to keep the ground clean.''"}, {"type": "choice", "q": "What is the week about?", "options": ["Doing small acts to make the school and city better.", "A sports match.", "A photo show.", "A maths test."], "answer": "A", "explanation": "通知主体=文明小举动。"}]'::jsonb, '[{"word": "citizen", "cn": "公民"}]'::jsonb),
  ('46a4da42-ca54-a6d3-3a80-0bdc2062400c', 8, 'junior_fltrp', 'wy8A', 'U6', 'During the storm', '暴风雨中(过去进行时)', 'A: What were you doing when the storm started, Ben?
B: I was walking home from school. The wind was blowing hard.
A: That sounds scary! Were you afraid?
B: A little. Rain was falling everywhere, so I ran to a shop.
A: Good thinking. What were the other people doing?
B: Most of them were waiting inside too, until the storm passed.', 'A:暴风雨开始时你在做什么,Ben?B:我正走路放学回家,风刮得很大。A:听着吓人!你害怕吗?B:有点。雨到处下,所以我跑进一家店。A:机智。其他人在做什么?B:大多也在里面等,直到暴风雨过去。', NULL, 'fable', 'dialogue', 31, 1, '[{"type": "choice", "q": "What was Ben doing when the storm started?", "options": ["Sleeping.", "Playing games.", "Walking home from school.", "Eating dinner."], "answer": "C", "explanation": "''I was walking home from school.''"}, {"type": "choice", "q": "What is the dialogue mainly about?", "options": ["How to cook in the rain.", "What people were doing during a storm.", "Why storms are fun.", "A school trip."], "answer": "B", "explanation": "主题=暴风雨中人们在做什么。"}]'::jsonb, '[{"word": "storm", "cn": "暴风雨"}, {"word": "blowing", "cn": "刮(blow的进行式)"}]'::jsonb),
  ('d8cf070f-7782-6f47-ad83-26ca3ea156c8', 8, 'junior_fltrp', 'wy8A', 'U6', 'A brave neighbour', '勇敢的邻居(过去进行时)', 'A: Did you hear about the fire last night?
B: Yes! Everyone was sleeping when it started.
A: How did people get out?
B: Mr Li was walking his dog nearby. He saw the smoke and shouted to wake everyone.
A: What a brave man!
B: He is. Because he was helping, everyone got out safely.', 'A:你听说昨晚的火灾了吗?B:听说了!起火时大家都在睡觉。A:人们怎么出来的?B:李先生正在附近遛狗,他看到烟就大喊叫醒所有人。A:多勇敢的人!B:是的,因为他帮忙,大家都安全出来了。', NULL, 'fable', 'dialogue', 27, 2, '[{"type": "choice", "q": "What was Mr Li doing when the fire started?", "options": ["Sleeping.", "Cooking.", "Watching TV.", "Walking his dog nearby."], "answer": "D", "explanation": "''Mr Li was walking his dog nearby.''"}, {"type": "choice", "q": "Why did everyone get out safely?", "options": ["Because Mr Li saw the smoke and warned them.", "Because it was raining.", "Because the fire was small.", "Because they were awake."], "answer": "A", "explanation": "李先生发现烟、叫醒大家。"}]'::jsonb, '[{"word": "fire", "cn": "火灾"}, {"word": "smoke", "cn": "烟"}]'::jsonb),
  ('6cb25f56-ceb4-92e9-82bd-21e19f155c2d', 8, 'junior_fltrp', 'wy8A', 'U6', 'The earthquake drill', '地震演练(过去进行时)', 'A: What were you doing when the drill bell rang?
B: I was writing in my notebook. Then we all got under our desks.
A: Did everyone stay calm?
B: Yes. The teacher was counting to keep us calm.
A: Drills like this are really useful.
B: They are. They help us know what to do in real danger.', 'A:演练铃响时你在做什么?B:我正在本子上写字,然后我们都躲到桌子下。A:大家都镇定吗?B:是的,老师在数数让我们镇定。A:这样的演练真有用。B:是的,它们帮我们知道真正危险时该怎么做。', NULL, 'fable', 'dialogue', 29, 1, '[{"type": "choice", "q": "What was the teacher doing to keep everyone calm?", "options": ["Singing.", "Running.", "Counting.", "Reading."], "answer": "C", "explanation": "''The teacher was counting to keep us calm.''"}, {"type": "choice", "q": "Why are drills useful?", "options": ["They are fun games.", "They help us know what to do in real danger.", "They waste time.", "They are noisy."], "answer": "B", "explanation": "''They help us know what to do in real danger.''"}]'::jsonb, '[{"word": "drill", "cn": "演练"}, {"word": "calm", "cn": "镇定的"}]'::jsonb),
  ('1879c2ab-0734-143c-32de-0f6e47106abf', 8, 'junior_fltrp', 'wy8A', 'U6', 'The night of the flood', '独白·洪水之夜(过去进行时)', 'It was raining hard that night, and the river was rising fast. My family was sleeping when a neighbour knocked on our door. ''The water is coming!'' he shouted. My father was carrying my little sister while my mother grabbed some food. We were running to higher ground as the water reached our steps. Many neighbours were helping each other in the dark. That night, I saw how brave ordinary people can be. We were all afraid, but we did not give up.', '那晚雨下得很大,河水涨得飞快。邻居敲门时我家人都在睡觉。『水来了!』他喊道。爸爸抱着小妹妹,妈妈抓了些吃的。水漫到台阶时,我们正往高处跑。黑暗中,许多邻居在互相帮助。那晚我看到普通人能有多勇敢。我们都害怕,但没有放弃。', NULL, 'fable', 'passage', 45, 1, '[{"type": "choice", "q": "What was the father doing as they left?", "options": ["Carrying the little sister.", "Grabbing food.", "Knocking on doors.", "Sleeping."], "answer": "A", "explanation": "''My father was carrying my little sister.''"}, {"type": "choice", "q": "What did the writer learn that night?", "options": ["How to swim.", "Why rivers are dangerous.", "How to cook.", "How brave ordinary people can be."], "answer": "D", "explanation": "''I saw how brave ordinary people can be.''"}]'::jsonb, '[{"word": "flood", "cn": "洪水"}, {"word": "rising", "cn": "上涨(rise的进行式)"}, {"word": "grabbed", "cn": "抓(grab的过去式)"}]'::jsonb),
  ('2c9c7a79-a40a-d759-5610-60af1c1583c5', 8, 'junior_fltrp', 'wy8A', 'U6', 'A hero at sea', '独白·海上英雄(过去进行时)', 'Last summer, my uncle saved a boy at the beach. That afternoon, many people were swimming and playing in the sea. Suddenly, a big wave pulled a young boy far from the shore. The boy was waving his arms and calling for help. While others were shouting, my uncle jumped into the water. He was swimming as fast as he could. He reached the boy and brought him back to the beach. Everyone cheered. My uncle just smiled and said any of us would do the same.', '去年夏天,叔叔在海滩救了一个男孩。那天下午,许多人在海里游泳玩耍。突然,一个大浪把一个小男孩卷离岸边。男孩挥着胳膊呼救。别人还在喊时,叔叔跳进水里。他拼命游。他游到男孩身边,把他带回海滩。大家欢呼。叔叔只是笑笑说,我们任何人都会这么做。', NULL, 'fable', 'passage', 47, 2, '[{"type": "choice", "q": "What was the boy doing when the wave pulled him away?", "options": ["Sleeping on the sand.", "Swimming and playing in the sea.", "Eating lunch.", "Reading a book."], "answer": "B", "explanation": "''many people were swimming and playing... a big wave pulled a young boy.''"}, {"type": "choice", "q": "What is the passage mainly about?", "options": ["How to swim fast.", "Why the sea is dangerous.", "How the writer''s uncle bravely saved a boy at the beach.", "A summer holiday plan."], "answer": "C", "explanation": "全文讲叔叔勇救男孩。"}]'::jsonb, '[{"word": "wave", "cn": "海浪;挥手"}, {"word": "shore", "cn": "岸"}]'::jsonb),
  ('ded04dd5-416d-11a6-5584-cbc82d8d4228', 8, 'junior_fltrp', 'wy8A', 'U6', 'Safety First Week', '通知·安全第一周(过去进行时/主动)', 'Hello, students. Here is some news about our Safety First Week. Next week, we will learn some safety skills. On Monday, we will practise what to do during an earthquake. On Wednesday, a firefighter will teach us how to stay safe. On Friday, we will make a family safety plan. Staying calm can save lives. Come and learn with us!', '同学们好,关于安全第一周的通知。上学期消防演练时,你们大多镇定、行动迅速。下周我们将学更多安全技能。周一,练习地震时该怎么做。周三,一位消防员教我们如何保持安全。周五,我们做一个家庭安全计划。保持镇定能救命。快来和我们一起学!', NULL, 'fable', 'notice', 33, 1, '[{"type": "choice", "q": "Who will teach students on Wednesday?", "options": ["A firefighter.", "A doctor.", "A police officer.", "A teacher."], "answer": "A", "explanation": "''a firefighter will teach us how to stay safe.''"}, {"type": "choice", "q": "What is Safety First Week about?", "options": ["A sports day.", "A photo show.", "A food festival.", "Learning safety skills and how to stay calm in danger."], "answer": "D", "explanation": "通知主体=学安全技能。"}]'::jsonb, '[{"word": "firefighter", "cn": "消防员"}, {"word": "earthquake", "cn": "地震"}]'::jsonb);

-- 断言
DO $$
DECLARE tot int; badq int; poll int; peru int;
BEGIN
  SELECT count(*) INTO tot FROM public.junior_listening_exercises WHERE publisher='junior_fltrp' AND volume='wy8A';
  IF tot<>36 THEN RAISE EXCEPTION 'total=% 期望36', tot; END IF;
  SELECT count(*) INTO badq FROM public.junior_listening_exercises WHERE publisher='junior_fltrp' AND volume='wy8A' AND jsonb_array_length(questions)<>2;
  IF badq<>0 THEN RAISE EXCEPTION '题数≠2的篇=%', badq; END IF;
  SELECT count(*) INTO poll FROM public.junior_listening_exercises WHERE volume='wy8A' AND publisher<>'junior_fltrp';
  IF poll<>0 THEN RAISE EXCEPTION 'pep_polluted=%', poll; END IF;
  SELECT count(*) INTO peru FROM (SELECT unit FROM public.junior_listening_exercises WHERE publisher='junior_fltrp' AND volume='wy8A' GROUP BY unit HAVING count(*)<>6) t;
  IF peru<>0 THEN RAISE EXCEPTION '每单元≠6篇的单元数=%', peru; END IF;
  RAISE NOTICE 'OK: wy8A 听力 % 篇 · 6单元各6 · 每篇2题', tot;
END $$;

COMMIT;
SELECT unit, count(*) 篇, sum((audio_url IS NULL)::int) 待生成音频 FROM public.junior_listening_exercises WHERE publisher='junior_fltrp' AND volume='wy8A' GROUP BY unit ORDER BY unit;